/* @lc app=leetcode id=4009 lang=kotlin */ class Solution { fun go(dm: IntArray, fu: IntArray, ps: IntArray, memo: HashMap<Int, Pair<Int, Int>>, i: Int, f0: Int, d0: Int, d1: Int): Pair<Int, Int> = if (i == dm.size) 0 to 0 else memo.getOrPut(((i * 51 + f0) * 21 + d0) * 21 + d1) { (fu[1] - (ps[i] - (fu[0] - f0))).let { f1 -> listOf(0, 1).filter { j -> (if (j == 0) f0 else f1) >= dm[i] }.map { j -> maxOf(0, if (j == 0) d0 else d1).let { w -> maxOf(0, (if (j == 0) d1 else d0) - w).let { dO -> go(dm, fu, ps, memo, i + 1, if (j == 0) f0 - dm[i] else f0, if (j == 0) dm[i] else dO, if (j == 1) dm[i] else dO).let { s -> (1 + s.first) to maxOf(w, s.second) } } } }.let { c -> if (c.isEmpty()) 0 to 0 else c.reduce { a, b -> if (a.first != b.first) (if (a.first > b.first) a else b) else (if (a.second <= b.second) a else b) } } } } fun minMaxWaitingTime(demand: IntArray, fuel: IntArray): Int = go(demand, fuel, demand.runningFold(0) { a, b -> a + b }.toIntArray(), HashMap(), 0, fuel[0], 0, 0).let { if (it.first == 0) -1 else it.second } }